var o=[{title:`Základy kliku`,text:`Položte ruce tam, kde je to pohodlné, držte tělo v jedné linii od ramen po kyčle, spouštějte se s lokty pod úhlem, který ramena snesou, a odtlačte se od podlahy. Lopatky se při kliku přirozeně pohybují po žebrech. Nenechte kyčle propadnout ani nevystrkujte hlavu dopředu jen proto, abyste započítali opakování.`},{title:`Výběr varianty`,text:`Klik o zeď bývá nejsnazší. Následuje klik s rukama na pevné desce nebo lavici, pak klik na kolenou nebo celý klik na podlaze. Později můžete zvednout nohy nebo přidat zátěž, aby byl těžší. Zda je pro vás snazší varianta na kolenou, nebo s vyvýšením, závisí na páce a pohodlí. Zvednutí rukou je jednoduchý způsob, jak tlačit menší část své tělesné hmotnosti.`},{title:`Bench press a tlaky s jednoručkami`,text:`Na lavici pevně zapřete chodidla, nastavte stabilní polohu trupu a ramen a spouštějte váhy pod kontrolou. Činka drží ruce na místě, zatímco jednoručky nechají úchop volněji se pohybovat, ale vyžadují kontrolu na každé straně. Těžké pokusy o bench press vyžadují schopného pomocníka nebo vhodné bezpečnostní vybavení.`},{title:`Časté omyly`,text:`Lokty nemusí zůstat přilepené k žebrům a neměly by ani vždy mířit rovně do stran. Zvolte šířku úchopu a dráhu loktů, které vám umožní pohybovat se silně a pohodlně. Lopatky nezůstávají zmrazené v jedné poloze při každém tlaku a kliky na podlaze a bench press na ně kladou různé nároky.`},{title:`Použití v TrainUp`,text:`Držte se jedné varianty kliku a zapisujte její opakování, dokud nebudete připraveni postoupit dál. V průběhu týdne vyvažujte horizontální tlaky přítahy. Pokud máte citlivá zápěstí nebo ramena, přidejte je jako omezení v Profilu, aby váš plán vybíral jen tlaky, které vám vyhovují.`}];var a=[{label:`Knihovna cviků ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: technika posilování (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`NSCA: bezpečnost a základy silového tréninku`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var n={sections:o,sources:a};export{n as default,o as sections,a as sources};